question.answer:
package main

func send(words []string, out chan string) {
	for _, word := range words {
		out <- word
	}
}

func take(n int, in chan string) []string {
	got := make([]string, 0, n)
	for range n {
		got = append(got, <-in)
	}
	return got
}

