question.answer:
package main

func bake(loaves []string) <-chan string {
	hatch := make(chan string)
	go func() {
		defer close(hatch)
		for _, loaf := range loaves {
			hatch <- loaf
		}
	}()
	return hatch
}

func collect(in <-chan string) []string {
	var got []string
	for loaf := range in {
		got = append(got, loaf)
	}
	return got
}

