question.answer:
package main

func poll(in <-chan string) (string, bool) {
	select {
	case motion, ok := <-in:
		return motion, ok
	default:
		return "", false
	}
}

func sit(motions <-chan string, done <-chan struct{}) []string {
	var heard []string
	for {
		select {
		case motion := <-motions:
			heard = append(heard, motion)
		case <-done:
			return heard
		}
	}
}
